// Source geometry and route order are kept separate from verified geographic positions.
const network=createMetroNetwork(MetroNetworkData);
let networkRoute='all',networkReverse=false,networkActive=null,networkOrigin='maharagama',networkDestination='ekala',networkChoices=[],networkSaved=[];
try{networkSaved=JSON.parse(localStorage.getItem('metroNetworkSaved')||'[]')}catch{}
let diagramCounter=0;
const ns=id=>network.stops[id],nr=id=>network.routes[id],stopName=id=>ns(id)?.name.en||id;
const routeColor=id=>nr(id).color;
function routeTag(id){return `<span class="network-tag" style="--route-color:${routeColor(id)}">${id}</span>`}
function networkNotice(){return `<div class="source-note">Published stop order & schematic map. GPS stop pins, timetables and live service status are not verified.</div>`}
function networkPathTitle(p){return p.legs.map(l=>l.routeId).join(' → ')}
function routeSelect(id){networkRoute=id;networkReverse=false;networkActive=null;activePlan=null;state.trip=false;render()}
function routeDisplayName(r){return r.terminals.en.replace(' to ',' ↔ ')}
function routeDirectory(q=''){let text=q.toLowerCase().trim();let arr=network.data.routes.filter(r=>[r.id,r.name.en,r.terminals.en,...r.orderedStops.flatMap(id=>Object.values(ns(id).name))].join(' ').toLowerCase().includes(text));return arr.length?arr.map(r=>`<button class="network-routecard ${networkRoute===r.id?'selected':''}" onclick="openNetworkRoute('${r.id}')">${routeTag(r.id)}<span><b>${safe(routeDisplayName(r))}</b><small>${r.distanceKm} km · ${r.orderedStops.length} stop positions${r.id==='CM06'?' · circular':''}</small></span>${ic('arrow')}</button>`).join(''):'<p class="empty">No route matches. Try a place or route number.</p>'}
function networkPlanCard(p,active=false){return `<article class="journeycard network-journey"><div class="journeybody"><div class="between"><span class="triptitle">${active?'YOUR CONNECTED JOURNEY':'PUBLISHED CONNECTION'}</span><span class="pill neutral">${p.changes?p.changes+' change'+(p.changes===1?'':'s'):'Direct'}</span></div><h2 style="font-size:23px;margin:18px 0 10px">${safe(stopName(p.from))} → ${safe(stopName(p.to))}</h2><div class="network-legstrip">${p.legs.map(l=>routeTag(l.routeId)).join(ic('arrow'))}</div><p class="sub">${p.changes?'Change at '+p.transfers.map(stopName).map(safe).join(', '):'Stay on the same route.'}</p><div class="access-note">Bus times and platform distances are unavailable. This is a route connection, not a timed catch prediction.</div><button class="primary full" style="margin-top:17px" onclick="${active?'networkJourneyDetails(networkActive,true)':"inspectNetworkConnection('"+p.id+"')"}">Stops, transfers & directions ${ic('arrow')}</button></div><div class="journeyfooter"><button onclick="saveNetworkConnection()">${ic('star')}Save journey</button><button onclick="openNetworkMap()">${ic('explore')}Network map</button></div></article>`}
home=function(){return `<div class="homehero"><div class="between"><span class="eyebrow">YOUR EVERYDAY JOURNEY</span><button class="textbtn" onclick="networkSources()">Route sources ${ic('arrow')}</button></div><h1>${profile?'Good day, '+profile+'.':'Where are you heading?'}</h1><div class="hero-meta">7 routes · 110 named stops <span style="float:right">Published network</span></div></div>${networkActive?networkPlanCard(networkActive,true):`<article class="journeycard"><div class="journeybody"><div class="between"><span class="triptitle">THE METRO NETWORK</span><span class="pill neutral">7 routes</span></div><h2 style="font-size:27px;margin:19px 0 9px">One journey.<br>Every connection.</h2><p class="sub">Find your route, follow the stops, and see where to change buses.</p><button class="primary full" style="margin-top:22px" onclick="planJourney()">${ic('search')}Where would you like to go?</button></div><div class="journeyfooter"><button onclick="setTab('routes')">${ic('bus')}Browse all routes</button><button onclick="openNetworkMap()">${ic('explore')}Open network map</button></div></article>`}<section class="section mobile-network"><div class="sectionhead between"><h2>Your Metro network</h2><button class="textbtn" onclick="openNetworkMap()">Explore map</button></div>${inlineNetworkPreview()}</section><section class="section"><div class="sectionhead between"><h2>Published routes</h2><button class="textbtn" onclick="setTab('routes')">View all</button></div>${routeDirectory()}</section><button class="walletpeek" style="margin-top:22px" onclick="setTab('wallet')">${ic('wallet')}<span><strong>Your LMT Go wallet</strong><small>Rs ${balance.toLocaleString()}.00 · demo wallet</small></span><span style="margin-left:auto">${ic('arrow')}</span></button><p class="bottomnote">${network.data.retrievedAt} source snapshot · Independent redesign. No connection to operator GPS, payments or live arrivals.</p>`};
routesPanel=function(){if(networkRoute!=='all')return selectedRoutePanel();return `<div class="screen-heading"><span class="eyebrow">THE COMPLETE PUBLISHED NETWORK</span><h1>Explore Metro.</h1><p class="sub">Seven routes. Every published stop in order.</p></div><button class="quicksearch" onclick="planJourney()">${ic('search')}<span><b>Find a route or connection</b><small>Choose any published stops</small></span>${ic('arrow')}</button><div class="searchbox row">${ic('search')}<input placeholder="Route or stop · English, සිංහල, தமிழ்" aria-label="Search all routes and stops" oninput="document.getElementById('networkRouteList').innerHTML=routeDirectory(this.value)"></div><div id="networkRouteList">${routeDirectory()}</div><div class="mobile-network" style="margin-top:20px">${inlineNetworkPreview()}</div>${networkNotice()}<button class="textbtn full" onclick="networkSources()">Sources, attribution & data coverage</button>`};
function selectedRoutePanel(){let r=nr(networkRoute),order=[...r.orderedStops];if(networkReverse)order.reverse();return `<button class="textbtn" onclick="networkRoute='all';render()">← All routes</button><div class="screen-heading">${routeTag(r.id)}<h1 style="font-size:26px">${safe(routeDisplayName(r))}</h1><p class="sub">${r.distanceKm} km · ${order.length} published stop positions</p></div><div class="directiontabs"><button class="${!networkReverse?'selected':''}" onclick="networkReverse=false;render()">${safe(stopName(r.orderedStops[0]))} →</button><button class="${networkReverse?'selected':''}" onclick="networkReverse=true;render()">← ${safe(stopName(r.orderedStops.at(-1)))}</button></div><p class="tiny">${r.id==='CM06'?'Circular stop order.':'Stop order towards '+safe(stopName(order.at(-1)))+'.'} Actual departures and directional boarding platforms need confirmation.</p><div class="mobile-network" style="margin:18px 0">${inlineNetworkPreview()}</div><section class="route-stop-list">${order.map((id,i)=>`<button class="network-stop-row" onclick="openNetworkStop('${id}')"><span class="stopnumber" style="--route-color:${r.color}">${i+1}</span><span><b>${safe(stopName(id))}</b><small>${network.served(id).map(r=>r.id).join(' · ')}${ns(id).interchange?' · map interchange':''}</small></span>${ic('pin')}</button>`).join('')}</section>${networkNotice()}`}
function openNetworkRoute(id){networkRoute=id;networkReverse=false;state.tab='routes';render();$('#panel').scrollTop=0;window.scrollTo({top:0,behavior:'smooth'})}
function inlineNetworkPreview(){return `<div class="network-preview"><div class="preview-diagram">${networkSvg(false)}</div><button class="secondary full" onclick="openNetworkMap()">Zoom & tap stops ${ic('arrow')}</button></div>`}
function networkSvg(interactive=true){let key='network-'+(++diagramCounter),rId=networkRoute;let highlighted=networkActive?new Set(networkActive.legs.map(l=>l.routeId)):rId==='all'?null:new Set([rId]);let used=highlighted?new Set([...highlighted].flatMap(id=>nr(id).orderedStops)):null;let labels=network.data.stops.filter(s=>!used||used.has(s.id));return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1180 1075" class="network-svg" aria-label="Published schematic network. Diagram positions are not GPS coordinates." role="img"><defs><pattern id="${key}-grid" width="45" height="45" patternUnits="userSpaceOnUse"><path d="M45 0H0V45" stroke="#e9e9ec" stroke-width=".5" fill="none"/></pattern></defs><rect width="1180" height="1075" fill="#fcfcfd"/><rect width="1180" height="1075" fill="url(#${key}-grid)"/><g class="network-viewport">${network.data.routes.map(r=>`<polyline points="${r.schematic.points.map(p=>p.join(',')).join(' ')}" class="network-line" style="stroke:${r.color};opacity:${highlighted&&!highlighted.has(r.id)?.13:1}" stroke-width="${highlighted?.has(r.id)?7:5}"/>`).join('')}${network.data.stops.map(s=>{let muted=used&&!used.has(s.id);return `<g class="diagram-stop ${muted?'muted':''}" ${interactive?`role="button" tabindex="0" aria-label="${safe(s.name.en)}, stop details" data-stop="${s.id}" onclick="mapStopClick(event,'${s.id}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openNetworkStop('${s.id}')}">`:'>'}<circle cx="${s.x}" cy="${s.y}" r="13" fill="transparent" class="stop-hit"/><circle cx="${s.x}" cy="${s.y}" r="${s.interchange?5.5:3.4}" fill="white" stroke="#38383f" stroke-width="${s.interchange?2:1.2}"/>${!muted?`<text x="${s.label.x}" y="${s.label.y}" text-anchor="${s.label.anchor||'middle'}" class="diagram-label">${safe(s.name.en)}</text>`:''}</g>`}).join('')}${network.data.routes.filter(r=>!highlighted||highlighted.has(r.id)).map(r=>`<g transform="translate(${r.mapLabel.x} ${r.mapLabel.y})"><rect x="-23" y="-12" width="46" height="23" rx="5" fill="white" stroke="${r.color}"/><text text-anchor="middle" y="4" fill="#16161a" font-size="11" font-weight="700">${r.id}</text></g>`).join('')}</g></svg>`}
function networkLegend(){return `<button class="legend-route ${networkRoute==='all'?'active':''}" onclick="selectMapRoute('all')">All routes</button>${network.data.routes.map(r=>`<button class="legend-route ${networkRoute===r.id?'active':''}" onclick="selectMapRoute('${r.id}')"><i style="background:${r.color}"></i>${r.id}</button>`).join('')}`}
function networkMapMarkup(sheet=false){return `<div class="network-map-shell ${sheet?'sheet-network':''}"><div class="network-map-title"><span class="eyebrow">SIMPLIFIED ROUTE OVERLAY</span><h2>${networkRoute==='all'?'The Metro network':safe(routeDisplayName(nr(networkRoute)))}</h2><p class="tiny">Drag to pan · + / − to zoom · tap any stop</p></div><div class="network-legend">${networkLegend()}</div><div class="diagram-stage" id="${sheet?'sheet':'main'}-diagram">${networkSvg()}</div><div class="network-map-controls"><button aria-label="Zoom in on network" onclick="zoomNetwork(1.35)">+</button><button aria-label="Zoom out on network" onclick="zoomNetwork(1/1.35)">−</button><button aria-label="Reset network view" onclick="zoomNetwork(0)">${ic('locate')}</button></div><div class="network-map-foot"><span>110 source stops · schematic, not geographical</span><button onclick="networkSources()">Map credit & sources</button></div></div>`}
renderMap=function(){$('#maparea').innerHTML=networkMapMarkup();installDiagram($('#main-diagram'))};
function selectMapRoute(id){networkRoute=id;networkActive=null;let isSheet=!!$('#sheet-diagram');if(isSheet)openNetworkMap();else render()}
function openNetworkMap(){modal('Metro network & stops',networkMapMarkup(true));installDiagram($('#sheet-diagram'))}
viewMap=openNetworkMap;
function mapStopClick(event,id){event.stopPropagation();let stage=event.currentTarget.closest('.diagram-stage');if(stage?.dataset.dragged==='true')return;openNetworkStop(id)}
function installDiagram(stage){if(!stage)return;let group=stage.querySelector('.network-viewport');let transform={scale:1,x:0,y:0};const pointers=new Map();let start=null,pinch=null;function apply(){group.setAttribute('transform',`translate(${transform.x} ${transform.y}) translate(590 537.5) scale(${transform.scale}) translate(-590 -537.5)`)}stage._captureView=()=>({...transform});stage._restoreView=v=>{transform={...v};apply()};stage._zoom=f=>{if(f===0)transform={scale:1,x:0,y:0};else transform.scale=Math.max(.7,Math.min(6,transform.scale*f));apply()};stage.addEventListener('pointerdown',e=>{if(e.button&&e.button!==0)return;stage.dataset.dragged='false';pointers.set(e.pointerId,[e.clientX,e.clientY]);start={x:e.clientX,y:e.clientY,tx:transform.x,ty:transform.y};if(pointers.size===2){let a=[...pointers.values()];pinch={distance:Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1]),scale:transform.scale}}});stage.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===2&&pinch){let a=[...pointers.values()];transform.scale=Math.max(.7,Math.min(6,pinch.scale*Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1])/pinch.distance));stage.dataset.dragged='true';apply();return}if(!start)return;let dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)+Math.abs(dy)>5){stage.dataset.dragged='true';let bounds=stage.getBoundingClientRect();let ratio=Math.max(1180/bounds.width,1075/bounds.height);transform.x=start.tx+dx*ratio;transform.y=start.ty+dy*ratio;apply()}});for(const ev of ['pointerup','pointercancel','pointerleave'])stage.addEventListener(ev,e=>{pointers.delete(e.pointerId);if(pointers.size<2)pinch=null;if(!pointers.size)start=null});stage.addEventListener('wheel',e=>{e.preventDefault();stage._zoom(e.deltaY<0?1.12:1/1.12)},{passive:false})}
function zoomNetwork(f){let stage=$('#sheet-diagram')||$('#main-diagram');stage?._zoom(f)}
function stopGpsHTML(s){if(!s.gps)return `<div class="gps-unavailable"><b>GPS coordinates not published</b><p>The linked map gives this stop a position on a diagram. It does not provide a latitude/longitude or a verified roadside boarding pin.</p><p>We have not converted its diagram position into GPS.</p></div>`;let lat=Number(s.gps.lat),lng=Number(s.gps.lng);return `<div class="gps-coordinates"><span>Published stop coordinates</span><b>${lat.toFixed(6)}, ${lng.toFixed(6)}</b><button class="secondary full" onclick="copyStopGps('${s.id}')">Copy GPS coordinates</button></div>`}
function stopMapUrl(s){return s.gps?'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(s.gps.lat+','+s.gps.lng):'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(s.name.en+' bus stop, Sri Lanka')}
function copyStopGps(id){let s=ns(id);if(!s.gps){toast('No published GPS coordinates are available for this stop.');return}navigator.clipboard.writeText(s.gps.lat+', '+s.gps.lng).then(()=>toast('GPS coordinates copied.')).catch(()=>toast('Copy unavailable. Select the displayed coordinates.'))}
function openNetworkStop(id){let s=ns(id),services=network.served(id);modal(s.name.en,`<div class="network-stop-heading">${ic('pin')}<span class="eyebrow">PUBLISHED STOP · ${services.length>1?'SHARED BY '+services.length+' ROUTES':'METRO NETWORK'}</span><h2>${safe(s.name.en)}</h2><p>${safe(s.name.si)}<br>${safe(s.name.ta)}</p></div><div class="network-legstrip">${services.map(r=>`<button class="stop-route-link" onclick="closeModal();openNetworkRoute('${r.id}')">${routeTag(r.id)}</button>`).join('')}</div>${stopGpsHTML(s)}<a class="primary full external-directions" href="${stopMapUrl(s)}" target="_blank" rel="noopener noreferrer">${ic('pin')}${s.gps?'Open published GPS pin':'Search this stop in Google Maps'} ${ic('arrow')}</a>${!s.gps?'<p class="tiny">Opens a place-name search, not an exact stop pin. Confirm the boarding side before travelling.</p>':''}<div class="row" style="margin-top:18px"><button class="secondary full" onclick="networkOrigin='${id}';planJourney()">Start here</button><button class="secondary full" onclick="networkDestination='${id}';planJourney()">Go here</button></div><section class="section"><h2>Routes & neighbouring stops</h2>${services.map(r=>{let i=r.orderedStops.indexOf(id),before=r.orderedStops[i-1],after=r.orderedStops[i+1];return `<div class="stop-service">${routeTag(r.id)}<b>${safe(routeDisplayName(r))}</b><div>${before?`<button onclick="openNetworkStop('${before}')">← ${safe(stopName(before))}</button>`:'<span>Route start</span>'}${after?`<button onclick="openNetworkStop('${after}')">${safe(stopName(after))} →</button>`:'<span>Route end</span>'}</div></div>`}).join('')}</section><div class="access-note">Stop access, platform, crossing distance and wheelchair space are unverified. A shared stop name does not confirm that buses board from the same side of the road.</div><button class="textbtn full" onclick="networkSources()">View source & location coverage</button>`)}
function stopInputOptions(){return network.data.stops.filter(s=>network.served(s.id).length).map(s=>`<option value="${safe(s.name.en)}">${safe(s.name.si)} · ${safe(s.name.ta)}</option>`).join('')}
function resolveStop(value){let v=value.trim().toLowerCase();return network.data.stops.find(s=>s.id===v||Object.values(s.name).some(n=>n.toLowerCase()===v))?.id}
planJourney=function(){modal('Find your route & connections',`<p class="sub">Search any published stop in English, Sinhala or Tamil. We’ll connect routes using their shared stops.</p><form onsubmit="event.preventDefault();runNetworkPlan()"><label for="network-from">From</label><input id="network-from" list="network-stops" value="${safe(stopName(networkOrigin))}" placeholder="Starting stop" autocomplete="off" required><label for="network-to">To</label><input id="network-to" list="network-stops" value="${safe(stopName(networkDestination))}" placeholder="Destination stop" autocomplete="off" required><datalist id="network-stops">${stopInputOptions()}</datalist><button type="button" class="textbtn" onclick="let t=$('#network-from').value;$('#network-from').value=$('#network-to').value;$('#network-to').value=t">Swap direction</button><div class="access-note">Exact stop GPS and live arrivals are unavailable from the linked data. Select a named stop; we won’t guess your nearest stop or a catch time.</div><button class="primary full" style="margin-top:20px">Find route connections ${ic('arrow')}</button></form>${networkNotice()}<button class="textbtn full" onclick="openNetworkMap()">Choose a stop from the network map</button>`)};
function runNetworkPlan(){let a=resolveStop($('#network-from').value),b=resolveStop($('#network-to').value);if(!a||!b){toast('Choose a published stop from the suggestions.');return}if(a===b){toast('Choose a different destination.');return}networkOrigin=a;networkDestination=b;networkChoices=network.connections(a,b);showNetworkResults()}
function connectionOption(p,i){return `<article class="connectioncard"><div class="between"><b>${p.changes?p.changes+' change'+(p.changes===1?'':'s'):'Direct route'}</b><span class="pill neutral">${p.stopCount} stop intervals</span></div><div class="network-legstrip">${p.legs.map(l=>routeTag(l.routeId)).join(ic('arrow'))}</div><p class="sub">${p.changes?'Change at '+p.transfers.map(stopName).map(safe).join(', '):'No bus change required.'}</p><p class="tiny" style="margin:12px 0">${p.legs.map(l=>`${l.routeId} towards ${safe(routeDirection(l))}`).join('<br>')}</p>${p.changes?'<div class="source-note">Transfer walking distance and boarding sides are not published.</div>':''}<button class="secondary full" style="margin-top:15px" onclick="inspectNetworkConnection('${p.id}')">See every stop & transfer ${ic('arrow')}</button></article>`}
function routeDirection(l){let r=nr(l.routeId);return stopName(l.direction===1?r.orderedStops.at(-1):r.orderedStops[0])}
function showNetworkResults(){modal('Your route connections',`<span class="eyebrow">PUBLISHED STOP ORDER</span><h2 class="network-result-title">${safe(stopName(networkOrigin))} → ${safe(stopName(networkDestination))}</h2><p class="sub">Ranked by fewer route changes, then fewer stop intervals.</p><button class="textbtn" onclick="planJourney()">Edit starting point or destination</button>${networkChoices.length?networkChoices.map(connectionOption).join(''):'<div class="card empty"><h2>No connection within two changes</h2><p class="sub">Try another published stop or inspect the network map.</p></div>'}<div class="access-note">These are topological connections. Service availability, waiting times, walking distances and exact boarding pins require operator data.</div>`)}
function inspectNetworkConnection(id){let p=networkChoices.find(p=>p.id===id);if(p)networkJourneyDetails(p)}
function networkJourneyDetails(p,active=false){modal(active?'Your published-route journey':'Your stops & connections',`<div class="journeyhead"><div class="between"><span>Published route connection</span><span class="pill neutral">${p.changes?p.changes+' change'+(p.changes===1?'':'s'):'Direct'}</span></div><h2>${safe(stopName(p.from))} → ${safe(stopName(p.to))}</h2><div class="network-legstrip">${p.legs.map(l=>routeTag(l.routeId)).join(ic('arrow'))}</div><p class="tiny">No live timing or fare estimate is available.</p></div>${p.legs.map((l,i)=>`<section class="network-journey-leg"><div class="row">${routeTag(l.routeId)}<h2>Take ${l.routeId} towards ${safe(routeDirection(l))}</h2></div><button class="network-journey-stop" onclick="openNetworkStop('${l.from}')">${ic('pin')}<span>Board at<b>${safe(stopName(l.from))}</b></span>${ic('arrow')}</button><details class="intermediate-stops"><summary>${Math.max(0,l.stopIds.length-2)} intermediate stops · show stop order</summary>${l.stopIds.slice(1,-1).map(id=>`<button onclick="openNetworkStop('${id}')">${ic('pin')}${safe(stopName(id))}</button>`).join('')}</details><button class="network-journey-stop" onclick="openNetworkStop('${l.to}')">${ic('pin')}<span>${i===p.legs.length-1?'Get off at':'Get off here to change'}<b>${safe(stopName(l.to))}</b></span>${ic('arrow')}</button>${i<p.legs.length-1?`<div class="change-callout"><b>Change from ${l.routeId} to ${p.legs[i+1].routeId}</b><span>Both routes list ${safe(stopName(l.to))}. The exact platform, crossing and walking distance are not published.</span><button class="textbtn" onclick="openNetworkStop('${l.to}')">Transfer stop & map search →</button></div>`:''}</section>`).join('')}<div class="access-note">Route topology comes from the supplied reference map. Intermediate stop order can differ from other publications. Confirm current service and direction with Metro. No travel time, walk or GPS location is inferred from the diagram.</div>${active?`<button class="secondary full" style="margin-top:18px" onclick="networkActive=null;closeModal();render()">Stop following journey</button>`:`<button class="primary full" style="margin-top:18px" onclick="followNetworkConnection('${p.id}')">Follow this whole journey</button><button class="textbtn full" onclick="showNetworkResults()">Compare connections</button>`}`)}
function followNetworkConnection(id){networkActive=networkChoices.find(p=>p.id===id);activePlan=null;networkRoute='all';state.trip=false;following=false;state.tab='explore';closeModal();render();$('#panel').scrollTop=0;window.scrollTo({top:0,behavior:'smooth'});toast('Published-route journey added to Home. Live timing remains unavailable.')}
viewJourney=function(){if(networkActive)networkJourneyDetails(networkActive,true);else planJourney()};
function saveNetworkConnection(){if(!networkActive){planJourney();return}let key=networkActive.from+'|'+networkActive.to;if(!networkSaved.some(x=>x.from+'|'+x.to===key))networkSaved.push({from:networkActive.from,to:networkActive.to});try{localStorage.setItem('metroNetworkSaved',JSON.stringify(networkSaved))}catch{}toast('Published-stop journey saved in Journeys.')}
savedPanel=function(){return `<div class="screen-heading"><span class="eyebrow">YOUR METRO JOURNEYS</span><h1>Your everyday routes.</h1><p class="sub">Save connections between published stops.</p></div>${networkActive?networkPlanCard(networkActive,true):''}<section class="section"><h2>Saved connections</h2>${networkSaved.length?networkSaved.map((p,i)=>`<div class="card section"><h2>${safe(stopName(p.from))} → ${safe(stopName(p.to))}</h2><button class="textbtn" onclick="networkOrigin='${p.from}';networkDestination='${p.to}';networkChoices=network.connections(networkOrigin,networkDestination);showNetworkResults()">Find connections →</button><button class="textbtn" style="float:right" onclick="networkSaved.splice(${i},1);localStorage.setItem('metroNetworkSaved',JSON.stringify(networkSaved));render()">Remove</button></div>`).join(''):'<div class="card empty section">Plan a connection, follow it, then save it here.</div>'}<button class="primary full" style="margin-top:20px" onclick="planJourney()">Plan a journey</button></section>`};
function networkSources(){modal('Sources & map coverage',`<h2>7 routes · 110 named source stops</h2><p class="sub" style="margin-top:13px">Route order, route colours, distances, multilingual stop names and schematic geometry were retrieved on ${network.data.retrievedAt} from the reference map you supplied.</p><div class="source-links"><a href="https://metroroutesrilanka.netlify.app/" target="_blank" rel="noopener noreferrer">Metro Route Sri Lanka · reference network ↗</a><a href="https://lankametro.lk/en" target="_blank" rel="noopener noreferrer">Lanka Metro Transit · operator website ↗</a><a href="https://lankametro.lk/en/smartmetro" target="_blank" rel="noopener noreferrer">Official SmartMetro tracker ↗</a></div><div class="gps-unavailable"><b>GPS stop locations are not included</b><p>The map dataset contains x/y drawing positions, not latitude/longitude. The official tracker showed Offline / no stops in this browser during retrieval. No exact GPS pins have been invented.</p></div><div class="card section"><h2>What is verified here?</h2><ul><li>Seven route definitions and source stop order</li><li>All source schematic route lines</li><li>Connections at shared published stop names</li></ul><p class="tiny">Current service status, boarding platforms, live bus positions, GPS, timetables, fares, and accessible walking paths remain unverified.</p></div><p class="tiny">CM07 is not present in the supplied network. CM08’s source title says Kesbewa–Pettah while its line also starts at Makumbura; both are retained. Older “from September” status labels are not treated as current service confirmation.</p><p class="tiny">Schematic reference: <a href="https://x.com/nuuuwan" target="_blank" rel="noopener noreferrer">Nuwan</a>. Interactive reference map: <a href="https://www.linkedin.com/in/rasaljayasinghe/" target="_blank" rel="noopener noreferrer">Rasal Jayasinghe</a>. This app is an independent redesign.</p>`)}
stopDetails=function(){openNetworkStop(networkOrigin)};
// Keep the global action bar useful without advertising an unconnected bus ETA.
const networkBaseRender=render;render=function(){networkBaseRender();$('#rideDock').innerHTML=`<button class="dock-ticket" onclick="${networkActive?'networkJourneyDetails(networkActive,true)':'planJourney()'}">${ic('bus')}${networkActive?'Your journey':'Plan journey'}</button><button class="dock-journey" onclick="openNetworkMap()"><span><strong>${networkActive?networkPathTitle(networkActive):'7 routes · 110 source stops'}</strong><small>Explore the simplified network</small></span>${ic('arrow')}</button>`};
// The LMT app symbol replaces the generic Home glyph; no extra header account control.
const brandedNetworkRender=render;render=function(){brandedNetworkRender();const homeButton=$('#nav button');const icon=homeButton?.querySelector('svg');if(icon)icon.outerHTML='<svg class="lmt-home-icon" viewBox="0 0 32 32" aria-hidden="true"><path d="M6 4h24l-2.4 7H6zm0 9h21l-2.4 7H6zm0 9h18l-2.4 7H6z"/></svg>';document.querySelector('header .guest')?.setAttribute('aria-hidden','true')};
render();
